import {sessionViewport} from './viewport.mjs';
import{stepCar,checkpointHit,offTable,clamp,collideCarRect,onBoostStrip}from'./engine.mjs';
import {mountGameProgress,recordEvent} from './progression.mjs';
if(typeof mountGameProgress==='function')mountGameProgress('tabletop-racing');
const c=document.querySelector('#game'),x=c.getContext('2d'),start=document.querySelector('#start'),result=document.querySelector('#result'),lapEl=document.querySelector('#lap'),timeEl=document.querySelector('#time');let W,H,run=false,t0=0,last=0,lap=1,cp=0,stuck=0;let car={x:120,y:180,heading:0,speed:0,boost:100};const input={steer:0,gas:0,boost:false};let cps=[];
let orientationBlocked=innerHeight>=innerWidth;let props=[],boostStrip=null,boostStrip2=null,boostStrip3=null,impacts=0;let boostHits=new Set();
function size(){if(orientationBlocked)return;W=c.width=innerWidth*devicePixelRatio;H=c.height=innerHeight*devicePixelRatio;x.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);W=innerWidth;H=innerHeight;cps=[{x:W*.48,y:H*.25,r:44},{x:W*.78,y:H*.5,r:44},{x:W*.5,y:H*.78,r:44},{x:W*.2,y:H*.55,r:44}];props=[{n:'BOOK',x:W*.47,y:H*.48,w:100,h:48},{n:'PIZZA',x:W*.7,y:H*.72,w:90,h:52},{n:'TAPE',x:W*.3,y:H*.27,w:58,h:58},{n:'RULER',x:W*.58,y:H*.34,w:130,h:18},{n:'PENCIL',x:W*.39,y:H*.73,w:88,h:12},{n:'ERASER',x:W*.68,y:H*.22,w:46,h:26}];boostStrip={x:W*.34,y:H*.69,w:95,h:24};boostStrip2={x:W*.76,y:H*.38,w:78,h:20};boostStrip3={x:W*.23,y:H*.43,w:72,h:18}};addEventListener('resize',size);size();
function reset(){car={x:W*.14,y:H*.5,heading:0,speed:0,boost:100};lap=1;cp=0;stuck=0;impacts=0;boostHits=new Set();lapEl.textContent='LAP 1/2'}
function draw(){x.clearRect(0,0,W,H);x.fillStyle='#e8d9b8';x.fillRect(0,0,W,H);x.strokeStyle='#5b5142';x.lineWidth=42;x.beginPath();x.ellipse(W*.5,H*.5,W*.36,H*.31,0,0,Math.PI*2);x.stroke();x.strokeStyle='#c8ff1a';x.lineWidth=3;x.setLineDash([12,12]);x.beginPath();x.ellipse(W*.5,H*.5,W*.36,H*.31,0,0,Math.PI*2);x.stroke();x.setLineDash([]);props.forEach(({n,x:a,y:b,w,h})=>{x.fillStyle='#c9b78f';x.fillRect(a-w/2,b-h/2,w,h);x.fillStyle='#171512';x.font='10px Arial';x.fillText(n,a-w/3,b)});x.fillStyle='#c8ff1a66';x.fillRect(boostStrip.x-boostStrip.w/2,boostStrip.y-boostStrip.h/2,boostStrip.w,boostStrip.h);x.fillStyle='#171512';x.font='bold 9px Arial';x.fillText('BOOST',boostStrip.x-18,boostStrip.y+3);x.fillStyle='#c8ff1a55';x.fillRect(boostStrip2.x-boostStrip2.w/2,boostStrip2.y-boostStrip2.h/2,boostStrip2.w,boostStrip2.h);x.fillStyle='#171512';x.fillText('BOOST',boostStrip2.x-18,boostStrip2.y+3);x.fillStyle='#c8ff1a44';x.fillRect(boostStrip3.x-boostStrip3.w/2,boostStrip3.y-boostStrip3.h/2,boostStrip3.w,boostStrip3.h);x.fillStyle='#171512';x.fillText('BOOST',boostStrip3.x-18,boostStrip3.y+3);cps.forEach((p,i)=>{x.strokeStyle=i===cp?'#c8ff1a':'#17151255';x.lineWidth=5;x.beginPath();x.arc(p.x,p.y,p.r,0,7);x.stroke()});x.save();x.translate(car.x,car.y);x.rotate(car.heading);x.fillStyle='#171512';x.fillRect(-18,-10,36,20);x.fillStyle='#c8ff1a';x.fillRect(0,-7,13,14);x.restore();x.fillStyle='#171512';x.fillText('BOOST '+Math.round(car.boost)+'%',W-145,48)}
function loop(ts){const dt=Math.min((ts-last)/1000||0,.033);last=ts;if(run&&!orientationBlocked){stepCar(car,input,dt);for(const prop of props)if(collideCarRect(car,prop))impacts++;const onB1=onBoostStrip(car,boostStrip),onB2=onBoostStrip(car,boostStrip2),onB3=onBoostStrip(car,boostStrip3);if(onB1)boostHits.add(1);if(onB2)boostHits.add(2);if(onB3)boostHits.add(3);if(onB1||onB2||onB3){car.speed=Math.min(340,car.speed+85*dt);car.boost=Math.min(100,car.boost+18*dt)}if(checkpointHit(car,cps[cp])){cp++;if(cp===cps.length){cp=0;lap++;lapEl.textContent=`LAP ${Math.min(lap,2)}/2`;if(lap>2)finish()}}if(offTable(car,W,H)){reset()}if(input.gas&&car.speed<15)stuck+=dt;else stuck=0;if(stuck>1.6)reset();timeEl.textContent=((performance.now()-t0)/1000).toFixed(1)}draw();requestAnimationFrame(loop)}requestAnimationFrame(loop);
function finish(){run=false;clearInput();pauseButton.disabled=true;const t=(performance.now()-t0)/1000,b=Number(localStorage.shrunkRaceBest||0);recordEvent('race_complete',{time:t,impacts,boostsUsed:boostHits.size},'tabletop-racing');if(!b||t<b)localStorage.shrunkRaceBest=t;document.querySelector('#finish').textContent=t.toFixed(2)+' SEC';document.querySelector('#best').textContent='BEST '+Number(localStorage.shrunkRaceBest).toFixed(2);result.classList.remove('hidden')}
function go(){clearInput();paused=false;pausePanel.classList.add('hidden');pauseButton.disabled=false;reset();start.classList.add('hidden');result.classList.add('hidden');run=true;t0=performance.now();last=t0}document.querySelector('#drop').onclick=go;document.querySelector('#again').onclick=go;
const steer=document.querySelector('#steer'),gas=document.querySelector('#gas');let sp=null,gp=null,gy=0;steer.onpointerdown=e=>{if(!run||orientationBlocked||sp!==null)return;sp=e.pointerId;steer.setPointerCapture(sp)};steer.onpointermove=e=>{if(run&&e.pointerId===sp){const r=steer.getBoundingClientRect();input.steer=clamp((e.clientX-(r.left+r.width/2))/(r.width*.35),-1,1)}};steer.onpointerup=steer.onpointercancel=e=>{if(e.pointerId===sp){sp=null;input.steer=0}};gas.onpointerdown=e=>{if(!run||orientationBlocked||gp!==null)return;gp=e.pointerId;gy=e.clientY;input.gas=1;gas.setPointerCapture(gp)};gas.onpointermove=e=>{if(run&&e.pointerId===gp)input.boost=gy-e.clientY>32};gas.onpointerup=gas.onpointercancel=e=>{if(e.pointerId===gp){gp=null;input.gas=0;input.boost=false}};

const pauseButton=document.querySelector('#pause'),pausePanel=document.querySelector('#pause-panel');
let paused=false,pausedAt=0;
function clearInput(){
 const oldSp=sp,oldGp=gp;sp=null;gp=null;gy=0;input.steer=0;input.gas=0;input.boost=false;
 if(oldSp!==null&&steer.hasPointerCapture(oldSp))steer.releasePointerCapture(oldSp);
 if(oldGp!==null&&gas.hasPointerCapture(oldGp))gas.releasePointerCapture(oldGp);
}
function pauseRace(){if(!run)return;pausedAt=performance.now();run=false;paused=true;clearInput();pausePanel.classList.remove('hidden');document.querySelector('#resume').focus()}
function resumeRace(){if(!paused)return;t0+=performance.now()-pausedAt;last=performance.now();paused=false;clearInput();pausePanel.classList.add('hidden');run=true;pauseButton.focus()}
pauseButton.onclick=pauseRace;
document.querySelector('#resume').onclick=resumeRace;
document.querySelector('#restart').onclick=go;
document.querySelector('#pause-home').onclick=()=>{run=false;clearInput();location.href='../../'};
steer.onlostpointercapture=e=>{if(e.pointerId===sp){sp=null;input.steer=0}};
gas.onlostpointercapture=e=>{if(e.pointerId===gp){gp=null;input.gas=0;input.boost=false}};

let orientationSince=0;sessionViewport(v=>{orientationBlocked=v.blocked;if(v.blocked){clearInput();if(!orientationSince)orientationSince=performance.now();}else{if(orientationSince){if(run)t0+=performance.now()-orientationSince;orientationSince=0;}size();last=performance.now();}});
